package com.tanmay.corebanking.service;
import com.tanmay.corebanking.enums.AccountType; import com.tanmay.corebanking.exception.*; import com.tanmay.corebanking.model.*; import com.tanmay.corebanking.repository.*; import com.tanmay.corebanking.util.AccountNumberGenerator; import java.math.*; import java.util.*;
public class AccountService {private final AccountRepository accounts;private final UserRepository users;public AccountService(AccountRepository a,UserRepository u){accounts=a;users=u;} public BankAccount createAccount(User u,AccountType t,BigDecimal initial){if(initial==null||initial.compareTo(BigDecimal.ZERO)<0)throw new InvalidAmountException("Initial deposit cannot be negative.");String n=AccountNumberGenerator.generate();BankAccount a=t==AccountType.SAVINGS?new SavingsAccount(n,u.getUserId(),initial):new CurrentAccount(n,u.getUserId(),initial);accounts.save(a);u.addAccountNumber(n);users.save(u);return a;} public BankAccount getAccount(String n){return accounts.findByAccountNumber(n).orElseThrow(()->new AccountNotFoundException("Account not found: "+n));} public List<BankAccount> getUserAccounts(String u){return accounts.findByUserId(u);} public List<BankAccount> getCustomerAccounts(String u){return getUserAccounts(u);} }
